#!/usr/bin/env python3
"""Batch runner for Brown Spots, Texture, and Pores local validation."""

from __future__ import annotations

import argparse
import json
import shutil
from datetime import datetime
from pathlib import Path

from src.engines.brown_engine import BrownAreaAnalyzer
from src.engines.pores_engine import PoresAnalyzer
from src.engines.texture_engine import TextureAnalyzer
from src.preprocess.image_preprocessor import ImagePreprocessor
from src.utils.io_utils import cv_imread, cv_imwrite


PROJECT_ROOT = Path(__file__).resolve().parent
SUPPORTED_SUFFIXES = {".jpg", ".jpeg", ".png", ".bmp", ".webp"}


def _path(value: str) -> Path:
    candidate = Path(value).expanduser()
    return candidate if candidate.is_absolute() else PROJECT_ROOT / candidate


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="批量运行棕色斑、纹理和毛孔三项检测"
    )
    parser.add_argument(
        "--input-dir",
        default="test-output/visia报告测试原图",
        help="输入目录；默认使用从四份VISIA报告提取的标准照片",
    )
    parser.add_argument(
        "--output-dir",
        default="test-output/brown_texture_pores",
        help="输出目录",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    input_dir = _path(args.input_dir)
    output_dir = _path(args.output_dir)
    sources = sorted(
        path
        for path in input_dir.iterdir()
        if path.is_file() and path.suffix.lower() in SUPPORTED_SUFFIXES
    )
    if not sources:
        raise FileNotFoundError(f"没有可测试图片: {input_dir}")
    if output_dir.exists():
        shutil.rmtree(output_dir)
    output_dir.mkdir(parents=True)

    preprocessor = ImagePreprocessor(
        str(input_dir),
        str(output_dir / "preprocessed"),
        str(PROJECT_ROOT / "data" / "reference.jpg"),
    )
    brown = BrownAreaAnalyzer()
    texture = TextureAnalyzer()
    pores = PoresAnalyzer()
    records = []
    try:
        for source in sources:
            print(f"\n{'=' * 72}\n处理 {source.name}\n{'=' * 72}")
            image = cv_imread(str(source))
            if image is None:
                records.append({"source": source.name, "status": "failed", "error": "读取失败"})
                continue
            try:
                pre = preprocessor.preprocess_image(image)
                if pre.quality_status == "REJECT":
                    raise ValueError(f"质量门禁拒绝: {pre.quality_flags}")
                preview_dir = output_dir / "预处理" / source.stem
                preview_dir.mkdir(parents=True, exist_ok=True)
                cv_imwrite(str(preview_dir / "01_标准化分析图.jpg"), pre.analysis_image)
                cv_imwrite(str(preview_dir / "02_有效皮肤Mask.png"), pre.skin_mask)

                brown_result = brown.detect_brown(pre)
                BrownAreaAnalyzer.save_result(
                    brown_result, str(output_dir / "棕色斑"), source.stem
                )
                texture_result = texture.detect_texture(pre)
                TextureAnalyzer.save_result(
                    texture_result, str(output_dir / "纹理"), source.stem
                )
                pores_result = pores.detect_pores(pre)
                PoresAnalyzer.save_result(
                    pores_result, str(output_dir / "毛孔"), source.stem
                )
                records.append(
                    {
                        "source": source.name,
                        "status": "success",
                        "quality_status": pre.quality_status,
                        "quality_flags": pre.quality_flags,
                        "brown_spot_count": brown_result.brown_spot_count,
                        "texture_feature_count": texture_result.texture_feature_count,
                        "texture_raised_like_count": texture_result.raised_like_count,
                        "texture_depressed_like_count": texture_result.depressed_like_count,
                        "pore_count": pores_result.pore_count,
                    }
                )
                print(
                    f"棕色斑={brown_result.brown_spot_count} | "
                    f"纹理={texture_result.texture_feature_count}"
                    f"（黄={texture_result.raised_like_count}，"
                    f"蓝={texture_result.depressed_like_count}） | "
                    f"毛孔={pores_result.pore_count}"
                )
            except Exception as exc:
                records.append(
                    {
                        "source": source.name,
                        "status": "failed",
                        "error": f"{type(exc).__name__}: {exc}",
                    }
                )
                print(f"失败: {type(exc).__name__}: {exc}")
    finally:
        brown.close()
        preprocessor.close()

    summary = {
        "generated_at": datetime.now().astimezone().isoformat(),
        "input_dir": str(input_dir.resolve()),
        "output_dir": str(output_dir.resolve()),
        "visia_reference_note": (
            "visia3.pdf 的原始特征计数为棕色斑232、纹理1826、毛孔733；"
            "其他报告只提供常模百分位，不能直接与实例数比较。"
        ),
        "records": records,
    }
    (output_dir / "批量检测汇总.json").write_text(
        json.dumps(summary, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    success = sum(item["status"] == "success" for item in records)
    print(f"\n完成：成功 {success}/{len(records)}，输出目录：{output_dir}")
    return 0 if success == len(records) else 1


if __name__ == "__main__":
    raise SystemExit(main())

# -*- coding: utf-8 -*-
"""五项皮肤检测共用的详细量化结果写入工具。

JSON 保留结构化的总体、分区和候选实例数据；CSV 使用长表格式，避免
把多级指标或数百个候选点压缩到一行而丢失信息。
"""

from __future__ import annotations

import csv
import json
from pathlib import Path
from typing import Any

import numpy as np


REGION_NAMES = {
    "forehead": "额头",
    "left_cheek": "左脸颊",
    "right_cheek": "右脸颊",
    "nose": "鼻部",
    "chin": "下巴",
    "t_zone": "T区",
    "non_t_zone": "非T区",
}


def json_safe(value: Any) -> Any:
    """递归转换 NumPy 类型，确保所有详细指标可直接 JSON 序列化。"""
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, dict):
        return {str(key): json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [json_safe(item) for item in value]
    return value


def chinese_region(name: str) -> str:
    return REGION_NAMES.get(str(name), str(name))


def translate_region_statistics(
    statistics: dict[str, dict[str, Any]],
    field_labels: dict[str, str],
) -> dict[str, dict[str, Any]]:
    """把算法分区统计转换为用户可读的中文字段。"""
    output: dict[str, dict[str, Any]] = {}
    for region, values in (statistics or {}).items():
        translated: dict[str, Any] = {"区域名称": chinese_region(region)}
        for key, value in (values or {}).items():
            label = field_labels.get(str(key))
            if label:
                translated[label] = json_safe(value)
        output[chinese_region(region)] = translated
    return output


def translate_instances(
    instances: list[dict[str, Any]],
    field_labels: dict[str, str],
) -> list[dict[str, Any]]:
    """保留候选实例的量化字段，并统一替换为中文指标名称。"""
    output: list[dict[str, Any]] = []
    for index, instance in enumerate(instances or [], start=1):
        item: dict[str, Any] = {"实例序号": index}
        for key, label in field_labels.items():
            if key not in instance:
                continue
            value = instance[key]
            if key == "region":
                value = chinese_region(str(value))
            item[label] = json_safe(value)
        output.append(item)
    return output


def translate_fields(
    values: dict[str, Any],
    field_labels: dict[str, str],
) -> dict[str, Any]:
    """按白名单转换字段，防止内部实现字段直接暴露为英文指标名。"""
    return {
        label: json_safe(values[key])
        for key, label in field_labels.items()
        if key in values
    }


def build_detailed_payload(
    *,
    algorithm_name: str,
    source_name: str,
    quality_score: float,
    quality_status: str,
    quality_flags: list[str],
    overall: dict[str, Any],
    regions: dict[str, dict[str, Any]],
    instances: list[dict[str, Any]],
    disclaimer: str,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """构造五项检测统一的详细结果合同。"""
    payload: dict[str, Any] = {
        "算法名称": algorithm_name,
        "量化结果版本": "五项皮肤检测详细量化V1",
        "来源文件": str(source_name),
        "图像质量": {
            "质量分数": float(quality_score),
            "质量状态": str(quality_status),
            "质量标记": [str(flag) for flag in (quality_flags or [])],
        },
        "整体量化指标": json_safe(overall),
        "分区量化指标": json_safe(regions),
        "候选实例明细": json_safe(instances),
        "说明": disclaimer,
    }
    if extra:
        payload["补充量化信息"] = json_safe(extra)
    return payload


def _scalar_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, bool):
        return "是" if value else "否"
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    return str(value)


def _csv_rows(value: Any, path: list[str]) -> list[list[str]]:
    """将嵌套 JSON 展开成可筛选的长表 CSV。"""
    if isinstance(value, dict):
        rows: list[list[str]] = []
        for key, child in value.items():
            rows.extend(_csv_rows(child, [*path, str(key)]))
        return rows
    if isinstance(value, list):
        rows: list[list[str]] = []
        if not value:
            return [["/".join(path), "", "", "", ""]]
        for index, child in enumerate(value, start=1):
            rows.extend(_csv_rows(child, [*path, f"第{index}项"]))
        return rows
    level = path[0] if path else ""
    region = path[1] if len(path) > 2 and path[0] == "分区量化指标" else ""
    instance = path[1] if len(path) > 2 and path[0] == "候选实例明细" else ""
    metric = " / ".join(path[2:] if (region or instance) else path[1:])
    return [[level, region, instance, metric, _scalar_text(value)]]


def write_detailed_metrics(
    json_path: str | Path,
    csv_path: str | Path,
    payload: dict[str, Any],
) -> None:
    """写入 UTF-8 JSON 与 Excel 可直接打开的 UTF-8 BOM CSV。"""
    safe_payload = json_safe(payload)
    Path(json_path).write_text(
        json.dumps(safe_payload, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    rows = _csv_rows(safe_payload, [])
    with Path(csv_path).open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(["指标层级", "分区", "实例", "指标名称", "指标值"])
        writer.writerows(rows)

    旧格式仍要求 JSON/CSV 完全相等；详细格式的 JSON 含总体、分区和
    实例明细，CSV 是同一数据的长表展开，因此只校验中文字段与非空表格。
    """
    with open(metrics_path, "r", encoding="utf-8") as handle:
        metrics = json.load(handle)
    if not isinstance(metrics, dict) or not metrics:
        raise ValueError("量化 JSON 必须是非空对象")

    with open(report_path, "r", encoding="utf-8-sig", newline="") as handle:
        rows = list(csv.reader(handle))
    if not rows or not rows[0]:
        raise ValueError("量化 CSV 不能为空")

    # 旧版横向简表：继续严格保持历史合同，避免影响已接入的调用方。
    if all(
        isinstance(value, int) and not isinstance(value, bool)
        for value in metrics.values()
    ):
        normalized_metrics: dict[str, int] = {}
        for raw_name, raw_value in metrics.items():
            name = str(raw_name)
            if not any("\u4e00" <= character <= "\u9fff" for character in name):
                raise ValueError(f"量化指标名称必须使用中文: {name}")
            normalized_metrics[name] = raw_value
        if len(rows) != 2 or len(rows[0]) != len(rows[1]):
            raise ValueError("量化 CSV 必须严格为等长的表头行和数据行")
        try:
            csv_metrics = {name: int(value) for name, value in zip(rows[0], rows[1])}
        except ValueError as exc:
            raise ValueError("量化 CSV 的数据必须是整数") from exc
        if csv_metrics != normalized_metrics:
            raise ValueError("量化 JSON 与 CSV 的中文指标和值不一致")
        return normalized_metrics

    def validate_chinese_keys(value) -> None:
        if isinstance(value, dict):
            for name, child in value.items():
                name = str(name)
                if not any("\u4e00" <= character <= "\u9fff" for character in name):
                    raise ValueError(f"量化指标名称必须使用中文: {name}")
                validate_chinese_keys(child)
        elif isinstance(value, list):
            for child in value:
                validate_chinese_keys(child)

    validate_chinese_keys(metrics)
    if rows[0] != ["指标层级", "分区", "实例", "指标名称", "指标值"]:
        raise ValueError("详细量化 CSV 表头不符合约定")
    if len(rows) < 2:
        raise ValueError("详细量化 CSV 缺少指标数据")
    return metrics


