def _load_and_validate_metrics(
    metrics_path: str,
    report_path: str,
) -> dict:
    """加载量化结果，兼容旧简表与新的详细结构化指标。

    旧格式仍要求 JSON/CSV 完全相等；详细格式的 JSON 含总体、分区和
    实例明细，CSV 是同一数据的长表展开，因此只校验中文字段与非空表格。
    """
    with open(metrics_path, "r", encoding="utf-8") as handle:
        metrics = json.load(handle)
    if not isinstance(metrics, dict) or not metrics:
        raise ValueError("量化 JSON 必须是非空对象")

    with open(report_path, "r", encoding="utf-8-sig", newline="") as handle:
        rows = list(csv.reader(handle))
    if not rows or not rows[0]:
        raise ValueError("量化 CSV 不能为空")

    # 旧版横向简表：继续严格保持历史合同，避免影响已接入的调用方。
    if all(
        isinstance(value, int) and not isinstance(value, bool)
        for value in metrics.values()
    ):
        normalized_metrics: dict[str, int] = {}
        for raw_name, raw_value in metrics.items():
            name = str(raw_name)
            if not any("\u4e00" <= character <= "\u9fff" for character in name):
                raise ValueError(f"量化指标名称必须使用中文: {name}")
            normalized_metrics[name] = raw_value
        if len(rows) != 2 or len(rows[0]) != len(rows[1]):
            raise ValueError("量化 CSV 必须严格为等长的表头行和数据行")
        try:
            csv_metrics = {name: int(value) for name, value in zip(rows[0], rows[1])}
        except ValueError as exc:
            raise ValueError("量化 CSV 的数据必须是整数") from exc
        if csv_metrics != normalized_metrics:
            raise ValueError("量化 JSON 与 CSV 的中文指标和值不一致")
        return normalized_metrics

    # medical_metrics_v1：JSON 保存总体、分区、目标明细和质量控制；CSV
    # 仅展开同一份总体/分区摘要。逐列核对，避免云端返回两套相互矛盾指标。
    if metrics.get("指标版本") == "medical_metrics_v1":
        required_sections = {
            "检测项目", "指标版本", "成像与单位说明", "总体指标",
            "分区指标", "目标明细", "质量控制", "医学局限性",
        }
        missing = required_sections - set(metrics)
        if missing:
            raise ValueError(f"医学量化 JSON 缺少字段: {sorted(missing)}")
        if not isinstance(metrics["总体指标"], dict):
            raise ValueError("医学量化总体指标必须是对象")
        if not isinstance(metrics["分区指标"], list):
            raise ValueError("医学量化分区指标必须是列表")
        if len(rows) != len(metrics["分区指标"]) + 2:
            raise ValueError("医学量化 CSV 行数与 JSON 总体/分区数量不一致")
        if len(rows) > 20:
            raise ValueError("医学量化 CSV 超过20行医生摘要上限")
        header = rows[0]
        if "检测范围" not in header or "评估状态" not in header:
            raise ValueError("医学量化 CSV 缺少检测范围或评估状态列")
        if any(
            not any("\u4e00" <= character <= "\u9fff" for character in name)
            for name in header
        ):
            raise ValueError("医学量化 CSV 列名必须全部使用中文")
        json_rows = [metrics["总体指标"], *metrics["分区指标"]]
        for line_number, (csv_row, json_row) in enumerate(
            zip(rows[1:], json_rows), start=2
        ):
            if len(csv_row) != len(header):
                raise ValueError(f"医学量化 CSV 第{line_number}行列数不一致")
            csv_values = dict(zip(header, csv_row))
            for name in header:
                if name == "医学解释":
                    continue
                expected = json_row.get(name, "")
                if csv_values[name] != str(expected):
                    raise ValueError(
                        f"医学量化 CSV/JSON 不一致: 第{line_number}行 {name}"
                    )
        return metrics

    def validate_chinese_keys(value) -> None:
        if isinstance(value, dict):
            for name, child in value.items():
                name = str(name)
                if not any("\u4e00" <= character <= "\u9fff" for character in name):
                    raise ValueError(f"量化指标名称必须使用中文: {name}")
                validate_chinese_keys(child)
        elif isinstance(value, list):
            for child in value:
                validate_chinese_keys(child)

    validate_chinese_keys(metrics)
    if rows[0] != ["指标分类", "指标名称", "指标值"]:
        raise ValueError("详细量化 CSV 表头不符合约定")
    if len(rows) < 2:
        raise ValueError("详细量化 CSV 缺少指标数据")
    return metrics


