def write_medical_metrics(
    json_path: str | Path,
    csv_path: str | Path,
    payload: dict[str, Any],
    project: str,
) -> None:
    """保存结构化 JSON 和医生可直接阅读的单表 CSV。"""
    safe = json_safe(payload)
    Path(json_path).write_text(json.dumps(safe, ensure_ascii=False, indent=2, allow_nan=False), encoding="utf-8")
    columns = _csv_columns(project)
    rows = [safe["总体指标"], *safe["分区指标"]]
    interpretation = {
        "redness": "弥漫与局灶可见红色代理，不代表血流量或炎症诊断",
        "spots": "普通RGB图像可见色差斑点，不代表UV色斑或具体疾病",
        "brown": "普通RGB图像综合色素代理，不代表黑色素真实含量或深度",
        "texture": "二维可见表面纹理代理，不代表真实高度、深度或体积",
        "pores": "标准化照片中的可见毛孔负担，不代表深度、堵塞或皮脂量",
    }[project]
    with Path(csv_path).open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=columns, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            record = {key: row.get(key, "") for key in columns}
            record["医学解释"] = interpretation
            writer.writerow(record)


